(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sco"] = {"ui":{"skip":"Skip tae the content","back":"← Back tae AI-gile","lang.button":"Leid: {name}","lang.dialog":"Pick a leid","lang.search":"Seek leids","lang.none":"Nae leid matches","lang.notYet":"{name} isnae translatit yet","theme.aria":"Chynge atween licht an dairk theme","theme.toLight":"Chynge tae the licht theme","theme.toDark":"Chynge tae the dairk theme","index.title":"AI-gile: yer AI dev team, on the ae board","index.description":"AI-gile is a kanban board for AI codin teams. They wirk while ye sleep; ye get the ae wee pile o things tae decide, test an accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Yer AI dev team, on the ae&nbsp;board.","hero.alpha":"🐣 Steekit pre-alpha","hero.alphaTitle":"Early an unfinished: thanks for tryin it!","hero.lede":"They big while ye sleep. Ye wauken tae the ae wee pile: a few questions, a few things tae test, a purple diamond or twa. Clap, accept, an back tae yer coffee.","dl.windows":"Windows app","dl.browser":"Rin it in yer browser","dl.soon":"Comin soon","dl.notify":"🔔 Tell me when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team niver needs a stand-up coffee. (They dae stand-ups onieweys.)","pitch.h2":"AI-gile in as mony words as ye like","pitch.lede":"Pick a length, frae the ae word tae 144. Ilka length is its ain description, scrievit for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 anither version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} caird on the board richt noo","count.line.html.other":"{n} cairds on the board richt noo","features.aria":"Whit it dis","f.pile.h":"The ae pile for ye","f.pile.html":"<b>For ye</b> haulds awthing waitin on ye, athort ilka project: questions, things tae test, jobs only a body can dae. Yer queue tells ye whit's neist an hou lang it taks.","f.sleep.h":"Teams that wirk while ye sleep","f.sleep.p":"Ilka project haes a lead an a team o AI agents. Comment on a caird an the team wakes up, daes the wirk, an hauns it back wi steps a tired body can follae.","f.tester.h":"An AI tester checks first","f.tester.p":"Afore onything reaches ye, a tester follaes the steps in a copy o the app an shaws whit it saw, wi a screenshot. Flick thro the anes that passed an accept in a clap.","f.proof.h":"Proof, nae promises","f.proof.p":"Ilka haun-ower shaws whit chynged: the files, the diff, the screenshots. Nae openin ilka app tae see if it's duin.","f.chat.h":"Blether wi yer leads","f.chat.p":"A Discord-style rail: ae icon per project, purple diamonds for whit needs ye. Message a lead an idea; they turn it intae cairds an a plan, wi a ✅ Go button.","f.tidy.h":"Keeps itsel tidy","f.tidy.p":"Related cairds fauld intae ane, muddled titles get fixed, an a token check keeps the code lean. Fewer things tae flit atween, less tae think on.","f.private.h":"Yours, on yer computer","f.private.li1":"The board rins on yer ain machine an only answers tae ye.","f.private.li2":"Private DMs atween fowk are end-tae-end encryptit.","f.private.li3":"Nae accounts, nae trackers, nae cookies.","f.lang.h":"In yer ain leid","f.lang.p":"Ower 120 leids, frae Dutch, Welsh an Japanese tae pirate, Yoda an Klingon, wi a quick switch back tae English for the developer words.","tl.aria":"Timeline frae the first blether tae the roadmap","tl.h2":"Frae the first blether tae whit's neist","tl.lede":"Real dates an times, in yer ain time zone. Efter the day it's the plan, wi nae dates promised.","tl.today":"The day","tl.planned":"plannit","tl.cards.one":"{n} caird","tl.cards.other":"{n} cairds","join.h2":"Jyne in","join.lede":"AI-gile is bein biggit by a wee human an a hantle o patient agents. It's private for noo, in a steekit alpha wi freends. Fancy a shot when it opens up?","join.btn":"Register interest","join.small":"We'll email ye, naething else","footer.tag":"AI-gile. Nae trackers, nae cookies, nae stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","form.sending":"Sendin…","form.failed":"That didnae wirk: try again later.","form.offline":"Couldnae reach AI-gile: try again later.","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave yer email tae hear when AI-gile's steekit alpha or beta opens.","interest.h1":"🔔 Tell me when it opens","interest.lede":"AI-gile is in steekit pre-alpha. Leave yer email an we'll write the ae time, when there's a place for ye.","interest.email":"Yer email","interest.which":"Which test?","interest.alpha":"Steekit alpha: early, rouch, lots o chynges","interest.beta":"Beta: steadier, later","interest.both":"Either, whitever comes first","interest.submit":"Pit me on the list","interest.thanks":"Thanks! Ye're on the list.","licence.title":"AI-gile: business licence","licence.description":"Usin AI-gile in yer business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Usin AI-gile at wirk? Tell us wha ye are an whit ye dae. If it daes some guid, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"Whit ye dae","licence.how":"Hou it helps the warld","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Aw quiet","status.checking":"Checkin…","status.offline":"Cannae reach the status service richt noo (tryin again)","status.updated":"updatit {ago}","status.justNow":"jist noo","status.min":"{n} min syne","status.hours":"{n} h syne","status.days":"{n} d syne","live.h2":"Watch it bein biggit, live","live.caption":"Ilka caird is hid: ye see the shape o the wark, no the words.","live.watching.one":"live: {n} watchin","live.watching.other":"live: {n} watchin","live.offline":"The live board's takkin a wee breather. Come back suin.","live.cols":"Backlog|Tae dae|Gaun on|Team checkin|For ye tae test|For the team|Duin","live.last.now":"Last caird moved jist noo","live.last.min.one":"Last caird moved {n} min syne","live.last.min.other":"Last caird moved {n} min syne","live.last.hour.one":"Last caird moved {n} oor syne","live.last.hour.other":"Last caird moved {n} oors syne","live.last.day.one":"Last caird moved {n} day syne","live.last.day.other":"Last caird moved {n} days syne"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Haundit."]},{"n":2,"texts":["Robot kanban.","Agents, sortit.","Ideas, biggit."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["A kanban board rin by agents.","Ye write cairds. Agents big.","Free, local, tested, gey daft."]},{"n":8,"texts":["A free kanban board whaur AI agents wirk.","Write an idea. Agents big it. Ye accept.","Agile for the ae body an mony patient robots."]},{"n":13,"texts":["A kanban board on yer computer whaur AI agents tak up the cairds.","Write an idea. A team o agents bigs it. A tester checks it.","Free, nae accounts, nae trackers: a board, some robots, an ye in chairge."]},{"n":21,"texts":["AI-gile is a kanban board for wirkin wi AI codin agents. They tak up the cairds; ye test an accept them, an that's the lot.","Ilka project gets a lead an a team o AI agents. Comment on onie caird an the team gets stuck in tae the wirk.","A free, personal tae-dae board that rins on yer ain computer. The wirkers are robots. The ane that says aye is you."]},{"n":34,"texts":["Ye pit ideas on a board. A team o AI agents turns them intae wirkin features, tests them, an hauns them back wi steps tae try. Naething coonts as duin until ye say sae yersel.","AI-gile is a hamemade kanban board that Rich biggit wi a guid wheen o help frae the agents it noo manages. It's free, rins on yer computer, an is shared wi freends, nae sauld.","Picture an ordinar kanban board, wi columns frae Backlog tae Duin, except the cairds are ta'en up by AI agents. They report hou they're gettin on, ask questions when stuck, an aye wait on yer thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board whaur the team is made o AI agents. Ilka project haes a lead that plans the wirk an helpers that big it. When a feature is ready, an AI tester tries it oot an taks a screenshot, then it lands in yer pile. Accept it, or leave a comment an they rewirk it.","It started oot as ae body's wey o keepin track o lots o AI codin sessions at aince, an grew intae a richt board. It rins on yer machine, needs nae account, an haes nae trackers. It's free for freends an onybody that's curious. It's alsae unfinished, sae expect some rouch edges an the odd surprise.","Here's the honest version. Ye still hae tae hae the ideas, an ye still hae tae check the results. Whit AI-gile daes is awthing in atween: it keeps the cairds in order, wakes the richt agent when ye comment, shaws exactly whit chynged, an keeps the lot in the ae short pile for ye."]},{"n":89,"texts":["AI-gile is a free kanban board that ye rin on yer ain computer. Insteid o fowk, ilka project haes a team o AI agents: a lead that turns yer ideas intae cairds an a plan, an helpers that tak up the cairds in priority order. When somethin is biggit, an AI tester follaes the test steps an shaws ye whit it saw. Then it waits in the ae pile merked For ye. Ye accept it, or ye comment an the team haes anither go. Naething iver reaches Duin wioot ye.","A wheen o things ye micht nae expect. A nicht watch keeps the Tae dae column topped up while ye sleep, pickin cairds that dinnae need an answer frae ye. A token coonter shaws hou muckle the agents hae uised the day an this week, an Nae Token Mode tells them tae stop spendin. Ye can message freends, an private messages are end-tae-end encryptit. The board speaks aboot 120 leids, includin Dutch, Flemish, pirate an Klingon. Nane o it costs a penny, an naebody's tryin tae sell it tae ye either.","AI-gile is a wee personal project, nae a company. Rich wantit tae look efter several AI codin projects wioot openin ilka app tae check on them, sae he an the agents biggit a board for it, then uised the board tae big the rest o itsel. It's in steekit pre-alpha, which means it wirks, mair or less, for a haunfu o freends. There's nae pricin page, nae newsletter an nae growth plan. If it sounds uisefu, ye can ask tae try it when it opens up a wee bit mair."]},{"n":144,"texts":["AI-gile is a kanban board for the ae human an a guid wheen o AI agents. It rins on yer ain computer an it's completely free. Ye add projects, an ilka project gets a lead an a wee team. Ye blether wi the lead, a bit like Discord, an describe an idea; the lead turns it intae cairds an a plan, then waits for ye tae chap Go. The team wirks thro the cairds in priority order, uisin a simple command line made for leid models. Afore onything comes back tae ye, an AI tester follaes the steps in a copy o the app an attaches a screenshot. Finished wirk lands in yer pile wi the chynged files an the diff. Ye accept it, or ye leave a comment an the team wakes up an tries again. Only ye can muive a caird tae Duin.","A day wi AI-gile, mair or less. In the evenin ye leave a few comments: this button's in the wrang place, that list should be sortit, could we hae a dairk mode. Ye gang tae yer bed. The agents read the comments, mak the chynges, test them an hand them back tae ye. If Tae dae rins dry, the nicht watch fills it frae the backlog wi cairds that need nae answer frae ye. In the mornin there's the ae short pile: a couple o questions an a few things tae try, ilk wi steps a sleepy body can follae an a screenshot o it wirkin. Ye click thro, accept the guid anes an send back the rest. A token coonter shaws whit it aw uised, an Nae Token Mode is there for lean weeks. Then ye hae yer breakfast, which the agents canna help wi yet.","First, whit AI-gile isnae. It isnae a startup, it isnae for sale, an naebody's collectin yer data. It's a free board that rins on yer computer, wi nae accounts, nae trackers an nae cookies. Whit it is: the ae tidy place tae see ilka AI codin project at aince, wi a team o agents daein the cairds an you makin the decisions. It faulds related cairds thegither, fixes muddled titles, an keeps an ee on hou lean the code bides. It speaks aboot 120 leids, frae Dutch an Flemish tae pirate an Klingon. Freends can message ilk ither, privately an encryptit. It wis biggit by Rich an a guid wheen o patient agents, mostly uisin itsel. It's in steekit pre-alpha, sae it's rouch in places. If it sounds like fun, ask nicely an ye micht get in early."]}],"quips":{"1":"The ae word. Bold. Maybe ower bold.","3":"Three words. Awready mair honest than maist product pages.","8":"Echt words. Still shorter than a stand-up.","21":"The lengths are story points, by the wey. O course they are.","55":"Fifty-five words. Twa cairds got finished while ye read that.","144":"That's the lang ane. There's nae 233. The agents hae gaen tae bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The vera first blether, afore there wis ony code.","first-board.name":"First board","first-board.line":"A board that keeps track o its ain biggin: cairds, columns, drag an drap, projects.","team-roles.name":"Team an roles","team-roles.line":"Agent profiles, team templates, spaces an wha daes whit.","install.name":"Install an releases","install.line":"A zip a freend can install, self-updates, channels an rowin back.","usage-saver.name":"Usage saver","usage-saver.line":"Mizzer whit runs cost, keep the code lean, save yer limit.","friends.name":"Freends an sharin","friends.line":"Private DMs, a scrambled relay, invites, roles an shared projects.","languages.name":"Leids","languages.line":"Ilka screen text in a leid file, wi Dutch an Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks ilka haun-ower first an shaws whit it saw.","website.name":"The website","website.line":"aigile.lol, the teaser an this timeline.","streaming.name":"Chat an streamin","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs an emojis.","no-ai.name":"Nae AI edition","no-ai.line":"A board for fowk that code wioot AI, an public boards.","night-watch.name":"Nicht watch","night-watch.line":"A watchman an Scrum Master keep the teams on task while ye sleep.","p-more.name":"Awthing else","p-more.line":"Wee ideas still waitin their turn.","p-android.name":"Phone an Android","p-android.line":"Reach yer board frae a phone, then a native Android app.","p-release.name":"Alpha an ayont","p-release.line":"Steekit alpha, the live site, then beta.","p-languages.name":"Mair leids","p-languages.line":"Mair than a hunner leids, an an immersion mode for learners.","p-engines.name":"Mair AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cairds an guard rails.","p-self.name":"Lookin efter ye","p-self.line":"Tired mode, self-care reminders an 4:20.","p-servers.name":"Servers an scale","p-servers.line":"Global server settings, roles an plannin for growth.","p-livestream.name":"Streamin extras","p-livestream.line":"Twitch chat, custom emojis an a public live view."}};
